import openpyxl,glob,re,collections,os
# load trio and carrier
twb=openpyxl.load_workbook('/workspace/tmp/downloads/Trio_Status.xlsx',data_only=True)
tws=twb.active; trows=list(tws.iter_rows(values_only=True))
carriers=set()
for r in trows[1:]:
 if r[3]=='Carrier': carriers.add(str(r[0]).strip())
files={}
for fn in glob.glob('*.xlsx'):
 m=re.search(r'CHIP_(?:(\\d+)|(SRR\\d+))',fn)
 if m: files[m.group(1) or m.group(2)] = fn
BAD_SO=['intron_variant','intergenic_variant','intergenic_region','3_prime_UTR_variant','5_prime_UTR_variant','5_prime_UTR_premature_start_codon_gain_variant','UTR_variant']
def numeric(s):
 try: return float(s)
 except: return None
counts=collections.Counter(); per={}
for sid in sorted(carriers):
 fn=files.get(sid)
 if not fn: continue
 wb=openpyxl.load_workbook(fn,data_only=True); ws=wb.active; rows=list(ws.iter_rows(values_only=True)); h2=rows[1]
 idx={n:i for i,n in enumerate(h2) if n}
 for r in rows[2:]:
  zy=r[idx['Zygosity']]
  if zy=='Reference': continue
  vaf=numeric(r[idx['Variant Allele Freq']])
  if vaf is None or vaf >= 0.3: continue
  so=str(r[idx['Sequence Ontology (Combined)']] or '')
  if any(term in so for term in BAD_SO): continue
  cl=r[idx['Classification']]
  if cl is None or str(cl).strip()=='' : continue
  counts['total'] +=1
  per[sid]=per.get(sid,0)+1
  if str(cl).strip() in ('Benign','Likely Benign'):
   counts['benign_lb'] +=1
print('counts',counts)
print('per',per)
